SATSUKI_KIRYUIN_SCENES = [
    {"name": "World: Satsuki Kiryuin, Recruit Check", "lines": [
        "background classroom", "me enters center with fade",
        "me (dismayed): You're standing in my school like you belong here. I'll ask three questions, and you'll answer them.",
        "player: Go on.",
        "me (pleased): Good. Meet me at the school at noon, and don't keep me waiting. I'm not patient with the ones who do.",
        "me: My mother keeps her questions to herself. I ask mine out loud, so the room can hear what I think."]},
    {"name": "World: Satsuki Kiryuin, Three Questions", "lines": [
        "background classroom", "me enters center with fade",
        "me: First question. Why do you stand where you stand? Answer without flinching.",
        "player: Because I want to be where the truth is.",
        "me (dismayed): Second question. What would you give up for it? Be quick, I have a class.",
        "player: Some of my comfort. Maybe more.",
        "me (pleased): Third question. Would you do it for me, or for yourself? Think before you answer, this one's the one I keep.",
        "player: For yourself. Then for you, if it's the same thing.",
        "me: Hm. That's the first honest answer I've had in years. It's written down now."]},
    {"name": "World: Satsuki Kiryuin, Small Circle", "lines": [
        "background classroom", "me enters center with fade",
        "me (pleased): You've been accepted into my small circle. Don't make me say it twice.",
        "player: Thank you, Satsuki.",
        "me (dismayed): Don't thank me. Stand where I can see you tomorrow, and keep your mouth shut about my mother.",
        "me: And I still haven't told you what I wrote for your third answer. Don't ask. You'll find out when it matters."]},
    {"name": "World: Satsuki Kiryuin, Life Plan", "lines": [
        "background sakura", "me enters left with slide",
        "me (dismayed): I've planned to overthrow my mother for years. It's a long list, and most of it is done.",
        "player: What's the first step?",
        "me (pleased): You'll see it tonight. It's Ryuko. She's been in the way since the first fight, and she's stronger than the reports.",
        "me: Meet me on the plaza this evening, and don't be late. I don't want to explain a plan twice."]},
    {"name": "World: Satsuki Kiryuin, Plaza Plan", "lines": [
        "background sakura", "me enters left with slide",
        "me (dismayed): The first step is to test Ryuko. I'd like to know if she can hold the blade, or whether she'll break under it.",
        "player: Are you going to fight her yourself?",
        "me: No. I'm going to watch you do it, and see how much you can stand, because that's what I'll need from you later.",
        "me (pleased): It's not a small plan. It's the first seam I'm going to cut, and it's a good one."]},
    {"name": "World: Satsuki Kiryuin, Ryuko Falls", "lines": [
        "cast ryuko as Ryuko Matoi",
        "background sakura",
        "me enters center with fade",
        "ryuko enters right with slide",
        "ryuko: {player} beat me, Satsuki. And you're doing this to get at your mother. I can see it on your face.",
        "me (pleased): Yes. But you'll help me, Ryuko, or you'll lose again, the same way you did the first time.",
        "ryuko: Ugh. Fine. I'm not losing my dad's blade to you either.",
        "me (dismayed): The blade's with my people now. It's not going to my mother. Think about that, and then ask me again."]},
    {"name": "World: Satsuki Kiryuin, Timing", "lines": [
        "background sakura", "me enters center with fade",
        "me (dismayed): Not yet. The timing isn't right. I'm not going to risk the family on a guess, or on a girl with a blade.",
        "player: When will it be?",
        "me (pleased): When I say so. Be ready, and stay out of my mother's sight until then.",
        "me: One more loose seam. She'll start pulling at it herself, and then I'll cut."]},
    {"name": "World: Satsuki Kiryuin, Rebellion Starts", "lines": [
        "background rooftop",
        "me enters left with rise",
        "me (dismayed): Mother's order is still standing. I'm going to start the rebellion tonight, whatever she thinks.",
        "player: Are you sure?",
        "me: No. But I'm not going to wait for her to decide my future, the way she decided Nui's.",
        "me (pleased): Stay on the roof. When she comes up the stairs, you'll see the first seam go.",
        "player: Who's going to be there?",
        "me (dismayed): Only you, and the family I've picked. Everyone else will see it in the morning.",
        "me: You asked me for three answers in the classroom. I'll give you one of mine tonight.",
        "player: That's a lot.",
        "me (pleased): It is. It's the one I was keeping for when it mattered. Now it does."]},
    {"name": "World: Satsuki Kiryuin, Rooftop Rebellion", "lines": [
        "background rooftop", "me enters center with fade",
        "me (dismayed): Mother's coming up the stairs. Stand behind me, and tell me if I'm wrong about this.",
        "player: You're not wrong.",
        "me (pleased): Good. Then watch me take the first step, the way I planned it years ago, in the back of the classroom.",
        "me: If I fall, pick up the answer I wrote down. It's the one that matters."]},
    {"name": "World: Satsuki Kiryuin, Ragyo Falls", "lines": [
        "cast ragyo as Ragyo Kiryuin",
        "background rooftop",
        "me enters center with fade",
        "ragyo enters right with slide",
        "ragyo: {player} beat me, Satsuki. Now you have to live with the family you've broken.",
        "me (dismayed): I'll live with it. You'll live with the choice you made, Mother, every time you pick up the thread.",
        "ragyo: Then go. I'll find you when the seams start to come apart, and they will.",
        "me (pleased): They already are. That's what I was waiting to see."]},
    {"name": "World: Satsuki Kiryuin, Begins", "lines": [
        "background rooftop", "me enters center with fade",
        "me (pleased): The rebellion has started. Mother's order is cut, and the family is ours to sew again, in our own way.",
        "player: Is that what you wanted?",
        "me (dismayed): It's what I'm going to do. What I wanted was for her to stop being the only voice in the room.",
        "me: You asked me for the third answer, in the classroom. Here it is. It was for both of us, the whole time."]},
    {"name": "World: Satsuki Kiryuin, Be Ready", "lines": [
        "background rooftop", "me enters center with fade",
        "me (dismayed): I'm not starting it tonight after all. Stay ready for the call, and don't let mother see you smile.",
        "player: I'll be ready.",
        "me (pleased): Good. And you'll learn the third answer when I've finished cutting. Not before.",
        "me: Go home. The roof's too cold for me to think on tonight."]},
]

